            return self.toCssWithOptions(dest, true);
    }

pub fn toCssWithOptions(self: CustomIdent, dest: *Printer, enabled_css_modules: bool) PrintErr!void {
            var css_module_custom_idents_enabled = false;
            _ = &css_module_custom_idents_enabled;
            if (enabled_css_modules) {
                if (dest.css_module) |*css_module| {
                    _ = &css_module;
                    css_module_custom_idents_enabled = (css_module.*).config.custom_idents;
                }
            }
            return dest.writeIdent(self.v, css_module_custom_idents_enabled);
    }

pub fn deepClone(self: CustomIdent, allocator: std.mem.Allocator) @This() {
            return css.implementDeepClone(@This(), (&self), allocator);
    }

pub fn hash(self: CustomIdent, hasher: *std.hash.Wyhash) void {
            return css.implementHash(@This(), (&self), hasher);
    }
    const This = @This();
};

pub const Result = css.Result;
pub const Printer = css.Printer;
pub const PrintErr = css.PrintErr;
pub const Specifier = css.css_properties.css_modules.Specifier;
pub const DashedIdentFns = DashedIdent;
pub const IdentFns = Ident;
pub const CustomIdentFns = CustomIdent;
pub const CustomIdentList = css.SmallList(CustomIdent, 1);
const Allocator = std.mem.Allocator;
const Symbol = bun.ast.Symbol;
